 /// Allocates `count` physically contiguous frames.
 ///
 /// # Returns
 ///
 /// Returns the base `FrameAddress` of the contiguous range.
 ///
 pub(super) fn alloc_contiguous(count: usize) -> Result<FrameAddress, Error> {
     instance().alloc_contiguous(count)
 }

 ///
