 ///
 /// Returns the number of free frames in the system.
 ///
 /// # Returns
 ///
 /// The number of free frames in the system.
 ///
 pub(super) fn free_count() -> usize {
     let inner = instance();
     inner.bitmap.number_of_bits() - inner.bitmap.usage()
 }

